const products = [
{id:1,name:'Forma — UI Kit',category:'templates',type:'ДИЗАЙН И ИНТЕРФЕЙСЫ',format:'FIGMA',price:2490,desc:'Компоненты и экраны для нового проекта',visual:'ui',art:'<div class="mini-ui"><small>forma / design essentials</small><h4>Less, but better.</h4><i></i><i></i><i></i></div>',badge:'Выбор редакции'},
{id:2,name:'Life OS — планировщик',category:'templates',type:'ПОРЯДОК В ДЕЛАХ',format:'NOTION',price:990,desc:'Задачи, привычки и идеи в одном месте',visual:'notion',art:'<div class="mini-notion">✳<h4>A little more focus.</h4><span>○ Weekly planner</span><span>✓ My projects</span><span>○ Good habits</span></div>'},
{id:3,name:'Playful — 3D-элементы',category:'graphics',type:'ГРАФИКА И ОБЪЕКТЫ',format:'PNG',price:1490,desc:'Объёмные формы для ярких композиций',visual:'shapes',art:'<div class="shape-grid">✳ ◒<br>✿ ✦</div>',badge:'Для смелых идей'},
{id:4,name:'Social Club — шаблоны',category:'templates',type:'СОЦИАЛЬНЫЕ СЕТИ',format:'FIGMA',price:1290,desc:'Единый стиль для постов и историй',visual:'social',art:'<div class="social-cards"><b>make<br>some<br>noise.<br>✳</b><b>your<br>daily<br>dose<br>of good.</b></div>'},
{id:5,name:'Everyday — пресеты',category:'tools',type:'ФОТО И ЦВЕТ',format:'XMP',price:790,desc:'Мягкий свет и естественные оттенки',visual:'photo',art:'<div class="landscape"><span>slow moments.</span></div>'},
{id:6,name:'Outline — набор иконок',category:'graphics',type:'ДЕТАЛИ И АКЦЕНТЫ',format:'SVG / PNG',price:690,desc:'Лаконичные символы для ваших макетов',visual:'icons',art:'<div class="icon-grid">⌘ ♡ ☼<br>↗ ◇ ✉<br>◎ ✳ ☷</div>'}
];
let cart=[];try{const saved=JSON.parse(localStorage.getItem('pixel-cart')||'[]');if(Array.isArray(saved))cart=[...new Set(saved)].filter(id=>products.some(p=>p.id===id));}catch{}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const grid=document.querySelector('#products');
function render(filter='all'){grid.innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="product"><div class="product-visual visual-${p.visual}">${p.badge?`<span class="badge">${p.badge}</span>`:''}${p.art}</div><div class="product-meta"><span>${p.type}</span><span>${p.format}</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="product-bottom"><strong>${money(p.price)}</strong><button class="add" data-add="${p.id}" aria-label="Добавить ${p.name} в корзину">${cart.includes(p.id)?'В корзине ✓':'В корзину + '}</button></div></article>`).join('');}
let activeFilter='all';document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});render(activeFilter);}));
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
function updateCart(){try{localStorage.setItem('pixel-cart',JSON.stringify(cart));}catch{}document.querySelector('#count').textContent=cart.length;document.querySelector('#cart-items').innerHTML=cart.length?cart.map(id=>{const p=products.find(p=>p.id===id);return `<div class="cart-row"><div>${p.name}<small>${p.format}</small></div><strong>${money(p.price)}</strong><button data-remove="${id}" aria-label="Удалить ${p.name}">×</button></div>`;}).join(''):'<p>Здесь пока пусто. Найдите что-нибудь для своей следующей идеи.</p>';document.querySelector('#total').textContent=money(cart.reduce((sum,id)=>sum+products.find(p=>p.id===id).price,0));render(activeFilter);}
grid.addEventListener('click',e=>{const button=e.target.closest('[data-add]');if(!button)return;const id=Number(button.dataset.add);if(cart.includes(id)){document.querySelector('#cart').showModal();return;}cart.push(id);updateCart();toast('Добавлено в вашу творческую корзину ✓');});
const dialog=document.querySelector('#cart');document.querySelector('#open-cart').onclick=()=>dialog.showModal();document.querySelector('#close-cart').onclick=()=>dialog.close();document.querySelector('#continue').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}const button=e.target.closest('[data-remove]');if(button){cart=cart.filter(id=>id!==Number(button.dataset.remove));updateCart();}});updateCart();
